import('ajv').then(({Ajv}) => {
  const ajv = new Ajv({allErrors: true, strict: false});
  const schema = {
    type: 'object',
    properties: {
      location: {type: 'string', description: 'City name'},
      units: {type: 'string', enum: ['celsius', 'fahrenheit'], description: 'Temperature units'},
    },
    required: ['location'],
  };
  const validate = ajv.compile(schema);
  console.log('missing location:', validate({units: 'celsius'}), validate.errors);
  console.log('wrong type + enum:', validate({location: 42, units: 'kelvin'}), validate.errors);
  console.log('errorsText:', ajv.errorsText(validate.errors, {dataVar: 'input'}));
});
